-- TOC entry 259 (class 1255 OID 25324)
-- Name: lesson_completion(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.lesson_completion() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin 
	insert into user_lesson_progress (id_user, id_lesson, status)
	select new.id_user, q.id_lesson, 'completed'
	from quizzes q
	where q.id = new.id_quiz and q.id_lesson is not null;
	
	return new;
end;
$$;


ALTER FUNCTION public.lesson_completion() OWNER TO postgres;

